mapper.select:
select
con.Con_Name as conName, con.Con_Party_B_Id as conPartyBId, c1.C_Name_History as wiUnitNameHistory, c2.C_Name_History as conPartyBNameHistory, c1.C_Name as wiUnitName, c2.C_Name as conPartyBName, c1.C_Abbreviation as wiUnitAbbName, c2.C_Abbreviation as conPartyBAbbName, mtl.Met_Name as metName, ead.Ead_Standard_Type as eadStandardType, ead.Ead_Supply_Order_No as eadSupplyOrderNo, ead.Ead_Brand_Name as eadBrandName, ead.Ead_Count as eadCount, ea.Ea_Code as eaCode, f.file_relation_id as fileRelationId, mn.* from Me_Witness_Inspection mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on mn.Wi_Unit_Id=c1.C_Id left join Me_Enter_Apply_Dtl ead on ead.Ead_Id=mn.Ead_Id left join Me_Enter_Apply ea on ead.Ea_Id=ea.Ea_Id left join Me_Type_Library mtl on mtl.Met_Id=ead.Met_Id left join SYS_Company c2 on con.Con_Party_B_Id=c2.C_Id left join Sys_File f on f.FileID=mn.Wi_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and con.Con_Party_B_Id = #{params.conPartyBId}
and mn.Ead_Id = #{params.eadId}
and mn.Ea_Id = #{params.eaId}
and mn.P_Id = #{params.pId}
and mn.Con_Id = #{params.conId}
and mn.Wi_Unit_Id = #{params.wiUnitId}
and mn.Wi_Order_No like concat('%',#{params.wiOrderNo},'%')
and mn.Wi_Code like concat('%',#{params.wiCode},'%')
and mn.Wi_Detection_Code like concat('%',#{params.wiDetectionCode},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Wi_End_Date DESC
